CREATE OR REPLACE FUNCTION public.meta_source_owner_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.org_meta_connections WHERE id=NEW.connection_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Connection organization mismatch';END IF;IF TG_OP='UPDATE' AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.page_id IS DISTINCT FROM OLD.page_id OR NEW.form_id IS DISTINCT FROM OLD.form_id) THEN RAISE EXCEPTION 'Meta source ownership is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER meta_source_owner_guard BEFORE INSERT OR UPDATE ON public.org_meta_sources FOR EACH ROW EXECUTE FUNCTION public.meta_source_owner_guard();
CREATE OR REPLACE FUNCTION public.meta_event_owner_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.source_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_meta_sources WHERE id=NEW.source_id AND company_id=NEW.company_id AND page_id=NEW.page_id AND form_id=NEW.form_id) THEN RAISE EXCEPTION 'Meta event source mismatch';END IF;RETURN NEW;END $$;
CREATE TRIGGER meta_event_owner_guard BEFORE INSERT OR UPDATE ON public.org_meta_events FOR EACH ROW EXECUTE FUNCTION public.meta_event_owner_guard();